import numpy as np
t=np.asarray(t);A=np.asarray(A);y=np.asarray(dA_dt)
def fit(p,deg=8):
    B=[t**k for k in range(deg)]
    X=np.column_stack(B+[b*A**p for b in B])
    c,res,_,_=np.linalg.lstsq(X,y,rcond=None)
    r=X@c-y
    return np.mean(r**2)/np.var(y)
for p in np.arange(0.5,3.01,0.25):
    print(p, fit(p))

