import numpy as np
from scipy.optimize import least_squares
t=np.asarray(t);A=np.asarray(A);y=np.asarray(dA_dt)
k=0.0129
S=y+k*t**2*A**1.5
forms={
 'G1 a exp(-b(t-c)^2)+d exp(-e t)+f': (lambda q: q[0]*np.exp(-q[1]*(t-q[2])**2)+q[3]*np.exp(-q[4]*t)+q[5], 6),
 'G2 a t^n exp(-b t)+e': (lambda q: q[0]*np.abs(t)**q[1]*np.exp(-q[2]*t)+q[3], 4),
 'G3 a(1-exp(-bt))exp(-dt)+e+f t': (lambda q: q[0]*(1-np.exp(-q[1]*t))*np.exp(-q[2]*t)+q[3]+q[4]*t, 5),
 'G4 a t exp(-b t)+c exp(-d t)+e+f/t': (lambda q: q[0]*t*np.exp(-q[1]*t)+q[2]*np.exp(-q[3]*t)+q[4]+q[5]/t, 6),
}
for name,(f,n) in forms.items():
    best=None
    for trial in range(60):
        rng=np.random.default_rng(trial)
        q0=rng.uniform(-2,2,n)
        for j in range(n):
            if name.startswith('G1') and j in (1,4): q0[j]=abs(q0[j])
            if name.startswith('G2') and j==2: q0[j]=abs(q0[j])
            if name.startswith('G3') and j in (1,2): q0[j]=abs(q0[j])
            if name.startswith('G4') and j in (1,3): q0[j]=abs(q0[j])
        if name.startswith('G1'): q0[2]=rng.uniform(0.5,3)
        try:
            with np.errstate(all='ignore'):
                s=least_squares(lambda q: np.nan_to_num(f(q)-S,nan=1e3,posinf=1e3,neginf=-1e3), q0, max_nfev=3000)
        except Exception: continue
        if best is None or s.cost<best.cost: best=s
    print(name, np.round(best.x,4), 'nmse', np.mean(best.fun**2)/np.var(S))
